async(page)=>{
const base='http://127.0.0.1:18762/final-preview-v4/';const click=n=>page.locator(`[data-label="${n}"]`).first().click();const input=n=>page.locator(`[data-label="${n}"] input, [data-label="${n}"] textarea`);const wait=f=>page.waitForURL('**/'+f+'.html*');const has=async t=>{if(!await page.getByText(t,{exact:false}).count())throw Error('Missing '+t)};
await page.goto(base+'00_welcome.html');await click('app_demo');await wait('04_today');await click('app_nav_plan');await wait('07_your_plan');
await input('plan_step_1').fill('Read one page of my notes');await input('plan_step_3').fill('Explain one finding');await click('app_nav_dashboard');await wait('04_today');await click('app_nav_plan');await wait('07_your_plan');if(await input('plan_step_3').inputValue()!=='Explain one finding')throw Error('Other edited step lost');
await page.locator('[data-label="app_step1"]').click({position:{x:10,y:70}});await wait('02_continue_your_work');await has('Read one page of my notes');await click('app_dashboard');await wait('04_today');await click('app_nav_plan');await wait('07_your_plan');
await input('plan_step_1').fill('');await click('personalized_start_1');await has('Add a small action first.');await input('plan_step_1').fill('X'.repeat(65));if((await input('plan_step_1').inputValue()).length!==48)throw Error('Step limit missing');await input('plan_step_1').fill('Read one page');await click('personalized_start_1');await wait('02_continue_your_work');await click('v3_finish_step');await wait('06_step_complete');await page.screenshot({path:'Coursework/prototype/tether-final-build/qa-app/12-completed.png'});await click('complete_home');await wait('page_1');await has('Finished the last step.');
await click('app_dashboard');await wait('04_today');await click('app_add');await wait('05_add_assignment');await input('assignment_title').fill('Cancelled draft title');await input('assignment_brief').fill('A requirement that should stay in the draft.');await click('app_review');await wait('06_check_requirements');await click('app_edit');await wait('05_add_assignment');await click('app_back');await wait('04_today');if(await page.getByText('Cancelled draft title',{exact:true}).count())throw Error('Draft leaked to dashboard');
await click('app_add');await wait('05_add_assignment');await input('assignment_title').fill('New biology assignment');await input('assignment_brief').fill('Describe how cells respond to environmental change.');await click('app_review');await wait('06_check_requirements');await click('app_build');await wait('07_your_plan');if(await input('plan_step_1').inputValue()!=='Identify the main requirements.')throw Error('New plan retained old steps');await click('app_nav_dashboard');await wait('04_today');await has('New biology assignment');await has('Identify the main requirements.');await page.screenshot({path:'Coursework/prototype/tether-final-build/qa-app/13-personalized-dashboard.png'});
await click('app_nav_settings');await wait('10_your_space');await click('app_pace');await wait('03_set_your_pace');await click('app_flexible');await click('app_continue');await wait('04_today');await click('app_nav_settings');await wait('10_your_space');await click('app_pace');await wait('03_set_your_pace');await has('Flexible study time');
return {ok:true,checks:['edits survive Today navigation','whole-row starts edited action','empty step blocked','48-character action limit','completion state','cancelled draft isolated','new plan resets old context','pace restored on revisit']};
}
